import matplotlib.pyplot as plt
import numpy as np
from matplotlib.collections import LineCollection

# PLOTTER CODE GENERATED BY GEMINI FOR EASE OF USE

def plot_trajectories(target, pursuer):
    target_path = np.array(target.pos_hist)
    pursuer_path = np.array(pursuer.pos_hist)
    
    # Calculate scalar speed magnitudes from velocity history
    pursuer_speeds = np.linalg.norm(np.array(pursuer.v_hist), axis=1)

    fig, ax = plt.subplots(figsize=(10, 6))
    
    # 1. Plot Target path
    ax.plot(target_path[:, 0], target_path[:, 1], 'r--', label='Target Path', alpha=0.7)

    # 2. Plot Pursuer path colored by speed using LineCollection
    points = pursuer_path.reshape(-1, 1, 2)
    segments = np.concatenate([points[:-1], points[1:]], axis=1)
    
    lc = LineCollection(segments, cmap='plasma', norm=plt.Normalize(pursuer_speeds.min(), pursuer_speeds.max()))
    lc.set_array(pursuer_speeds)
    lc.set_linewidth(2.5)
    line = ax.add_collection(lc)
    
    # Add a colorbar indicating speed scales
    cbar = fig.colorbar(line, ax=ax)
    cbar.set_label('Pursuer Speed (m/s)')

    # 3. Add a marker dot at the final position (point of interception)
    interception_point = pursuer_path[-1]
    ax.scatter([interception_point[0]], [interception_point[1]], color='lime', s=120, zorder=5, edgecolors='black', label='Interception Point')

    # Formatting
    ax.set_title('AIM-9M Proportional Navigation (Speed Colored Trajectory)')
    ax.set_xlabel('X Position (meters)')
    ax.set_ylabel('Y Position (meters)')
    ax.grid(True)
    ax.axhline(0, color='black', linewidth=0.5)
    ax.axvline(0, color='black', linewidth=0.5)
    ax.legend(loc='upper left')
    ax.axis('equal') 
    plt.show()